from rdkit import Chem
import numpy as np
mol = Chem.MolFromXYZFile("answer.xyz")
pos = mol.GetConformer().GetPositions()
syms = [a.GetSymbol() for a in mol.GetAtoms()]
n = len(syms)
cov = {"H":0.31,"C":0.76,"N":0.71,"O":0.66,"Se":1.20}
bonds = []
for i in range(n):
    for j in range(i+1,n):
        d = np.linalg.norm(pos[i]-pos[j])
        if d < cov[syms[i]]+cov[syms[j]]+0.45:
            bonds.append((i,j))
adj = {i:[] for i in range(n)}
for i,j in bonds:
    adj[i].append(j); adj[j].append(i)
# print Se and N and carbonyl C neighborhoods
for a in [0,1,20,2,21]:
    print(syms[a], a, "->", [(syms[b],b) for b in adj[a]])
# find 5-membered rings containing Se via simple cycle search
import itertools
def find_cycles(start):
    cycles=set()
    # BFS paths
    from collections import deque
    q=deque([(start,[start])])
    while q:
        cur,path=q.popleft()
        for nb in adj[cur]:
            if nb==start and len(path)>=4:
                cycles.add(tuple(sorted(path)))
            elif nb not in path and len(path)<6 and nb>start:
                q.append((nb,path+[nb]))
    return cycles
cyc = find_cycles(0)
for c in sorted(cyc, key=len):
    if len(c)<=6:
        print(len(c), [(syms[i],i) for i in c])
